const images = $('List Drive Images').all().map(i => i.json).filter(x => x.id);
const history = $('Read Post History').all().map(i => i.json).filter(x => x.image_file_id);
const batchStateRows = $('Read Batch State').all().map(i => i.json).filter(x => x.date);
const todayStr = $now.toFormat('yyyy-LL-dd');
const todayLogPrefix = 'LOG-' + $now.toFormat('yyyyLLdd');

const todayScheduled = history.filter(h => String(h.log_id || '').startsWith(todayLogPrefix));
const countToday = todayScheduled.length;
const offsetsMin = [0, 60, 120, 180, 240];

if (countToday >= offsetsMin.length) {
  return [{ json: { done: true, noImages: false, needStartTime: false, countToday } }];
}
if (images.length === 0) {
  return [{ json: { done: true, noImages: true, needStartTime: false, countToday } }];
}

const usedTodayIds = new Set(todayScheduled.map(h => h.image_file_id));
const availableImages = images.filter(img => !usedTodayIds.has(img.id));
if (availableImages.length === 0) {
  return [{ json: { done: true, noImages: true, needStartTime: false, countToday } }];
}

const nowUnix = Math.floor($now.toSeconds());
const todayBatchState = batchStateRows.find(r => r.date === todayStr);

let baseUnix;
if (todayBatchState && todayBatchState.base_time_unix) {
  baseUnix = Number(todayBatchState.base_time_unix);
} else {
  const defaultBase = $now.set({ hour: 20, minute: 00, second: 0, millisecond: 0 });
  const defaultBaseUnix = Math.floor(defaultBase.toSeconds());
  if (countToday === 0 && nowUnix > defaultBaseUnix - 300) {
    return [{ json: { done: false, noImages: false, needStartTime: true, countToday } }];
  }
  baseUnix = defaultBaseUnix;
}

const countMap = {};
for (const h of history) { countMap[h.image_file_id] = (countMap[h.image_file_id] || 0) + 1; }
const withCounts = availableImages.map(img => ({ file_id: img.id, file_name: img.name, web_view_link: img.webViewLink || '', times_posted: countMap[img.id] || 0 }));
const minCount = Math.min(...withCounts.map(i => i.times_posted));
const candidates = withCounts.filter(i => i.times_posted === minCount);
const chosen = candidates[Math.floor(Math.random() * candidates.length)];

let slotUnix = baseUnix + offsetsMin[countToday] * 60;
if (slotUnix - nowUnix < 900) { slotUnix = nowUnix + 900; }

return [{ json: { done: false, noImages: false, needStartTime: false, file_id: chosen.file_id, file_name: chosen.file_name, web_view_link: chosen.web_view_link, times_posted: chosen.times_posted, scheduled_unix: slotUnix, slot_index: countToday, countToday } }];

