const msg = $json.message;
const text = msg.text || '';
const chatId = msg.chat.id;

let driveFileId = null;
const entities = msg.entities || [];
let rawUrl = null;
for (const entity of entities) {
  if (entity.type === 'url') {
    const candidate = text.substring(entity.offset, entity.offset + entity.length);
    if (candidate.includes('drive.google.com')) { rawUrl = candidate; break; }
  }
  if (entity.type === 'text_link' && entity.url && entity.url.includes('drive.google.com')) { rawUrl = entity.url; break; }
}
if (!rawUrl) {
  const m = text.match(/https:\/\/drive\.google\.com\/[^\s]+/);
  if (m) rawUrl = m[0];
}
if (rawUrl) {
  const idMatch = rawUrl.match(/[-\w]{25,}/);
  driveFileId = idMatch ? idMatch[0] : null;
}

return [{ json: { chatId, userText: text, hasLink: !!driveFileId, extractedFileId: driveFileId } }];

const nowUnix = Math.floor(Date.now() / 1000);

const minimumScheduleUnix = nowUnix + 900; // 15 minutes later
const maximumScheduleUnix = nowUnix + (75 * 24 * 60 * 60);

function getSafeScheduledUnix(value) {
  const requestedUnix = Number(value);

  if (
    Number.isFinite(requestedUnix) &&
    requestedUnix >= minimumScheduleUnix &&
    requestedUnix <= maximumScheduleUnix
  ) {
    return Math.floor(requestedUnix);
  }

  return minimumScheduleUnix;
}


// =========================
// RETRY FLOW
// =========================

if ($input.item.json.retry === true) {

  const r = $input.item.json;

  return [{
    json: {
      file_id: r.file_id,
      file_name: r.file_name,
      description: r.description,
      chatId: r.chatId,
      scheduled_unix: getSafeScheduledUnix(r.scheduled_unix),
      mode: r.mode
    }
  }];
}


// =========================
// NORMAL / REPOST FLOW
// =========================

const fileId =
  $input.item.json.id ||
  $input.item.json.image_file_id;

const fileName =
  $input.item.json.name ||
  $input.item.json.image_name;

const isPendingReply =
  $input.item.json.image_file_id !== undefined;

const mode = isPendingReply ? 'reply' : 'repost';

const scheduledUnixFromPending =
  $input.item.json.scheduled_unix;

const ctx = $('Parse Telegram Message').item.json;


// =========================
// OUTPUT
// =========================

return [{
  json: {
    file_id: fileId,
    file_name: fileName,

    description:
      $input.item.json.description ||
      ctx.description ||
      '',

    chatId:
      $input.item.json.chatId ||
      ctx.chatId,

    scheduled_unix: getSafeScheduledUnix(
      scheduledUnixFromPending ||
      ctx.scheduled_unix
    ),

    mode: mode
  }
}];

const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Image = binaryBuffer.toString('base64');
const mimeType = ($input.item.binary && $input.item.binary.data && $input.item.binary.data.mimeType) || 'image/jpeg';
const ctx = $('Normalize Request').item.json;

return [{ json: { file_id: ctx.file_id, file_name: ctx.file_name, description: ctx.description, chatId: ctx.chatId, base64Image, mimeType } }];

