const response = $json;
const candidate = response.candidates?.[0];
const rawContent = candidate?.content?.parts?.[0]?.text || '';
const cleaned = String(rawContent).trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let captionData;
try {
  captionData = JSON.parse(cleaned);
  if (!captionData.caption || !captionData.hashtags) throw new Error('missing fields');
} catch (e) {
  captionData = {
    caption: 'নতুন পণ্য এসেছে! এখনই দেখুন।',
    hashtags: '#newarrival #shopping',
    _debug_error: e.message,
    _debug_raw: rawContent
  };
}

// লিটারাল \n এবং \r থাকলে সেগুলোকে আসল নিউলাইনে কনভার্ট করা
const formatNewlines = (str) => {
  if (typeof str !== 'string') return '';
  return str.replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n').replace(/\\r/g, '\n');
};

const cleanCaption = formatNewlines(captionData.caption);
const cleanHashtags = formatNewlines(captionData.hashtags);

const ctx = $('Normalize Request').item.json;
const finalMessage = cleanCaption + '\n\n' + cleanHashtags;

return {
  ...ctx,
  caption: cleanCaption,
  hashtags: cleanHashtags,
  finalMessage
};

