const pendingRow = $json;
const ctx = $('Parse Telegram Message').item.json;
const text = (ctx.userText || '').trim().toLowerCase();

let match = text.match(/(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?/);
let baseUnix = null;
let parseFailed = true;

if (match && match[1] !== undefined) {
  let hour = parseInt(match[1], 10);
  let minute = match[2] ? parseInt(match[2], 10) : 0;
  const ampm = match[3];
  if (!isNaN(hour) && hour >= 0 && hour <= 23 && minute >= 0 && minute < 60) {
    if (hour <= 12) {
      if (ampm === 'am') { if (hour === 12) hour = 0; }
      else { if (hour !== 12) hour += 12; }
    }
    const dt = $now.set({ hour: hour % 24, minute, second: 0, millisecond: 0 });
    baseUnix = Math.floor(dt.toSeconds());
    parseFailed = false;
  }
}

const nowUnix = Math.floor($now.toSeconds());
if (parseFailed || baseUnix === null) {
  baseUnix = nowUnix + 900;
  parseFailed = true;
} else if (baseUnix < nowUnix - 300) {
  baseUnix = nowUnix + 900;
}

return [{ json: { pending_id: pendingRow.pending_id, base_time_unix: baseUnix, chatId: ctx.chatId, parseFailed, image_file_id: pendingRow.image_file_id || '', image_name: pendingRow.image_name || '', description: pendingRow.description || '' } }];

